using System;
using System.Threading;
using System.Threading.Tasks;
using Grpc.Core;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace GrpcService.Services
{
    public class ConnectionPool : IDisposable
    {
        private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);
        private IntPtr _nativeBuffer;
        private bool _disposed;
        private int _refCount;
        private readonly ILogger<ConnectionPool> _logger;

        public ConnectionPool(ILogger<ConnectionPool> logger)
        {
            _logger = logger;
            _nativeBuffer = AllocateNativeBuffer(4096);
            _refCount = 1;
        }

        private static IntPtr AllocateNativeBuffer(int size)
        {
            return System.Runtime.InteropServices.Marshal.AllocHGlobal(size);
        }

        public void AddRef()
        {
            Interlocked.Increment(ref _refCount);
        }

        public void Release()
        {
            if (Interlocked.Decrement(ref _refCount) == 0)
            {
                FreeResources();
            }
        }

        private void FreeResources()
        {
            if (_nativeBuffer != IntPtr.Zero)
            {
                _logger.LogInformation("Freeing native buffer");
                System.Runtime.InteropServices.Marshal.FreeHGlobal(_nativeBuffer);
                _nativeBuffer = IntPtr.Zero;
            }
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        protected virtual void Dispose(bool disposing)
        {
            if (!_disposed)
            {
                _disposed = true;
                if (disposing)
                {
                    _semaphore.Dispose();
                }
                FreeResources();
            }
        }

        ~ConnectionPool()
        {
            Dispose(false);
        }
    }

    public class GracefulShutdownHandler : IHostedService
    {
        private readonly ConnectionPool _pool;
        private readonly ILogger<GracefulShutdownHandler> _logger;
        private CancellationTokenSource _cts;
        private Task _drainTask;

        public GracefulShutdownHandler(ConnectionPool pool, ILogger<GracefulShutdownHandler> logger)
        {
            _pool = pool;
            _pool.AddRef();
            _logger = logger;
            _cts = new CancellationTokenSource();
        }

        public Task StartAsync(CancellationToken cancellationToken)
        {
            _drainTask = DrainConnectionsAsync(_cts.Token);
            return Task.CompletedTask;
        }

        private async Task DrainConnectionsAsync(CancellationToken token)
        {
            try
            {
                while (!token.IsCancellationRequested)
                {
                    await Task.Delay(1000, token);
                }
            }
            catch (OperationCanceledException)
            {
                _logger.LogInformation("Drain loop cancelled, releasing pool reference");
            }
            finally
            {
                _pool.Release();
            }
        }

        public async Task StopAsync(CancellationToken cancellationToken)
        {
            _logger.LogInformation("Graceful shutdown initiated");
            _cts.Cancel();

            if (_drainTask != null)
            {
                await Task.WhenAny(_drainTask, Task.Delay(5000, cancellationToken));
            }

            _pool.Release();
            _cts.Dispose();
        }
    }

    public class HealthCheckService : Greeter.GreeterBase
    {
        private readonly ConnectionPool _pool;
        private readonly ILogger<HealthCheckService> _logger;

        public HealthCheckService(ConnectionPool pool, ILogger<HealthCheckService> logger)
        {
            _pool = pool;
            _logger = logger;
        }

        public override Task<HelloReply> SayHello(HelloRequest request, ServerCallContext context)
        {
            _logger.LogInformation("Health check from {Name}", request.Name);
            return Task.FromResult(new HelloReply { Message = "Healthy" });
        }
    }

    public static class HelloRequest
    {
        public string Name { get; set; }
    }

    public static class HelloReply
    {
        public string Message { get; set; }
    }

    public abstract class GreeterBase { public virtual Task<HelloReply> SayHello(HelloRequest r, ServerCallContext c) => throw new NotImplementedException(); }
    public static class Greeter { public class GreeterBase : Services.GreeterBase { } }
}
